 pickupInstrument(){if(!this.enabled||!this.bench||!this.ui.play135.bag156.prepared176.has('meter'))return false;if(this.view.bagBrowser157?.phase!=='closed'){this.pendingInstrument=true;return false;}if(this.held){if(this.held.kind==='instrument')return true;this.message('Tienes el filtro en la mano. Apóyalo antes de tomar el instrumento.');return false;}if(!this.instrumentPlaced&&!this.near(this.view.bagBrowser157.model.root,1.6)){this.message('Acércate a la bolsa para tomar el anemómetro.');return false;}if(this.instrumentPlaced&&!this.near(this.bench.instrument142)){this.message('Acércate al anemómetro que dejaste apoyado para recogerlo.');return false;}this.held=this.save(this.bench.instrument142,'instrument');this.instrumentPlaced=false;this.ui.state.choose('meter');this.bench.instrument142.visible=true;const item=this.view.bagBrowser157?.items.get('meter');if(item){item.visible=false;item.userData.outside188=true;}this.update(.0);this.message('Anemómetro en la mano. Acércate al ventilador y mantén E para medir.');return true;}
