 eventPoint(e){if(e)return e;const r=this.view.canvas.getBoundingClientRect();return{target:this.view.canvas,clientX:r.left+r.width/2,clientY:r.top+r.height/2,button:0,pointerId:188,preventDefault(){},stopImmediatePropagation(){}};}
