 if(!this.held&&hit?.id===s.step?.target&&['driver','brush','test'].includes(s.step.tool)){if(s.step.tool!=='test'&&!this.ui.play135.bag156.prepared176.has(s.step.tool)){void this.ui.play135.bag156.setOpen(true);return true;}if(!this.near(hit.target,1.4)){this.message('Acércate a la pieza para trabajar con la herramienta.');return true;}if(s.step.tool==='brush'&&!this.filterAtPad){this.message('Apoya primero el filtro sobre el tapete.');return true;}this.ui.state.choose(s.step.tool);this.toolWork={index:s.index,target:hit.id,tool:s.step.tool,event:e,elapsed:0,duration:s.step.tool==='brush'?.4:s.step.tool==='driver'?.8:1.2};this.ui.hand134?.play145(hit.target,s.step.tool);this.message('Mantén E o el clic sobre la pieza para '+(s.step.tool==='brush'?'cepillar':s.step.tool==='driver'?'girar la fijación':'realizar el ensayo')+'.');return true;}
 
